from pathlib import Path
import json,subprocess
base=Path.home()/".local/share/prediction-project-executor/campaigns/FULL-A2Z-LIVE-20261004-V4"
task="A2Z-V4-ASTRA-PREBUILD-DIRECT-20261007-R4P2"
out={}
for name in ("models/STATE.json","models/CONTINUATION.json","models/BLOCKER.json"):
    p=base/name
    if p.is_file():
        try: out[name]=json.loads(p.read_text(encoding="utf-8"))
        except Exception as e: out[name]={"read_error":repr(e)}
result=base/"model_results"/(task+".json")
out["result_exists"]=result.is_file()
unit="prediction-a2z-v4-model@A2Z-V4-ASTRA-PREBUILD-DIRECT-20261007-R4P2.service"
for cmdname,cmd in {
  "status":["systemctl","--user","status",unit,"--no-pager","-l"],
  "show":["systemctl","--user","show",unit,"-p","ActiveState","-p","SubState","-p","Result","-p","ExecMainStatus","-p","ExecMainCode","-p","ActiveEnterTimestamp","-p","InactiveEnterTimestamp"],
  "journal":["journalctl","--user","-u",unit,"-n","180","--no-pager"]
}.items():
    p=subprocess.run(cmd,capture_output=True,text=True)
    out[cmdname]={"rc":p.returncode,"stdout":p.stdout[-16000:],"stderr":p.stderr[-4000:]}
print("ERROR_CLASS=R4P2_POSTRETRY_STATE_DIAG",flush=True)
print("ERROR="+json.dumps(out,separators=(",",":"),sort_keys=True),flush=True)
raise SystemExit(1)
